以下代码演示了如何将笛卡尔型重叠矩阵Sbas转换为球谐型Sbas5D。代码在同一个循环中处理了列的右乘和行的左乘，利用球谐型函数数目少于笛卡尔型的特点直接覆盖原矩阵的适当位置。
```fortran
ipos5D=1
ipos6D=1
do ish=1,nshell
ishtyp5D=shelltype5D(ish)
ishtyp6D=shelltype(ish)
numshorb5D=type2norb(ishtyp5D)
numshorb6D=type2norb(ishtyp6D)
!Now contract columns
if (ishtyp5D==0.or.ishtyp5D==1.or.ishtyp5D==-1) sbas(:,ipos5D:ipos5D+numshorb5D-1)=sbas(:,ipos6D:ipos6D+numshorb6D-1)
if (ishtyp5D==-2) sbas(:,ipos5D:ipos5D+numshorb5D-1)=matmul(sbas(:,ipos6D:ipos6D+numshorb6D-1),conv5d6d)
if (ishtyp5D==-3) sbas(:,ipos5D:ipos5D+numshorb5D-1)=matmul(sbas(:,ipos6D:ipos6D+numshorb6D-1),conv7f10f)
if (ishtyp5D==-4) sbas(:,ipos5D:ipos5D+numshorb5D-1)=matmul(sbas(:,ipos6D:ipos6D+numshorb6D-1),conv9g15g)
!Now contract rows
if (ishtyp5D==0.or.ishtyp5D==1.or.ishtyp5D==-1) sbas(ipos5D:ipos5D+numshorb5D-1,:)=sbas(ipos6D:ipos6D+numshorb6D-1,:)
if (ishtyp5D==-2) sbas(ipos5D:ipos5D+numshorb5D-1,:)=matmul(conv5d6dtr,sbas(ipos6D:ipos6D+numshorb6D-1,:))
if (ishtyp5D==-3) sbas(ipos5D:ipos5D+numshorb5D-1,:)=matmul(conv7f10ftr,sbas(ipos6D:ipos6D+numshorb6D-1,:))
if (ishtyp5D==-4) sbas(ipos5D:ipos5D+numshorb5D-1,:)=matmul(conv9g15gtr,sbas(ipos6D:ipos6D+numshorb6D-1,:))
ipos5D=ipos5D+numshorb5D
ipos6D=ipos6D+numshorb6D
end do
sbas5D=sbas(1:nbasis5D,1:nbasis5D)

若显示格点文件处提示access denied，需在/usr/java/jre1.6.0_21/lib/security/java.policy文件中添加指定代码段，授予/sob/molproView/jmol/目录下Java程序访问本地文件的权限。
grant codeBase "file:/sob/molproView/jmol/*" {
permission java.security.AllPermission

proc atmlab {range id} {
set sel [atomselect $id $range]
set k 0
foreach i [$sel list] {
label add Atoms $id/$i
label textformat Atoms $k { %i }
label textoffset Atoms $k { -0.11 -0.0055 }
incr k
$sel delete
label textsize 1.2
- 若想让所有ID为3的体系的原子编号都显示，输入atmlab all 3
- 若想让只有在34号原子的5埃范围以内的原子的标签显示，输入atmlab "within 5 of index 34" 3

proc lab {} {
atmlab all [molinfo top]
运行lab就会把top的体系的原子编号都显示。

连接关系可以从自行提供的列表中读取，通过运行命令
[atomselect top all] setbonds {{1 2 3 4 7} 0 0 0 {5 6 7 0} 4 4 {4 0}}
即可将当前体系的连接关系修改为列表中定义的内容。

将下述代码复制到VMD控制台执行，可自定义supshow命令用于绘制
```tcl
proc supshow {fps1 fps2 space} {
for {set fps $fps1} {$fps<$fps2} {incr fps $space} {
set selca [atomselect top "name CA" frame $fps]
set calist [$selca get {x y z}]
for {set n 0} {$n<[expr [$selca num]-2]} {incr n 1} {
draw cylinder [lindex $calist $n] [lindex $calist [expr $n+1]] radius 0.1 filled yes resolution 20
$selca delete
echo "frame" $fps "done"
